from gurobipy import GRB
products = []
values = {}
weights = {}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    if 'ProductName' in vals and 'Value' in vals and ('Weight' in vals):
        pname = vals['ProductName']
        products.append(pname)
        try:
            values[pname] = int(vals['Value'])
            weights[pname] = int(vals['Weight'])
        except Exception as e:
            raise ValueError(f'Invalid Value or Weight for {pname}: {e}')
capacity = None
for rec in LEGACY_RECORDS:
    vals = rec['values']
    if 'Capacity' in vals:
        try:
            capacity = int(vals['Capacity'])
        except Exception as e:
            raise ValueError(f'Invalid Capacity: {e}')
        break
